CREATE TABLE IF NOT EXISTS richo_data_purposes(id uuid PRIMARY KEY,name text NOT NULL UNIQUE,purpose text NOT NULL,lawful_basis text NOT NULL,allowed_data jsonb NOT NULL DEFAULT '[]'::jsonb,retention_days integer,regions jsonb NOT NULL DEFAULT '[]'::jsonb,status text NOT NULL DEFAULT 'active',correlation_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_data_access_audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor text NOT NULL,section_id text,purpose_id uuid REFERENCES richo_data_purposes(id),data_class text NOT NULL,operation text NOT NULL,region text,allowed boolean NOT NULL,reason text,correlation_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_privacy_requests(id uuid PRIMARY KEY,subject_ref text NOT NULL,request_type text NOT NULL CHECK(request_type IN('access','export','delete','correct','restrict')),scope jsonb NOT NULL DEFAULT '{}'::jsonb,status text NOT NULL DEFAULT 'pending_verification',correlation_id text,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE TABLE IF NOT EXISTS richo_deletion_plans(id uuid PRIMARY KEY,subject_ref text NOT NULL,actions jsonb NOT NULL,status text NOT NULL DEFAULT 'awaiting_approval',approved_by text,correlation_id text,created_at timestamptz NOT NULL DEFAULT now(),executed_at timestamptz);
CREATE TABLE IF NOT EXISTS richo_consent_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),subject_ref text NOT NULL,purpose_id uuid REFERENCES richo_data_purposes(id),state text NOT NULL CHECK(state IN('granted','withdrawn','not_required')),source text,evidence jsonb NOT NULL DEFAULT '{}'::jsonb,effective_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS richo_privacy_subject_idx ON richo_privacy_requests(subject_ref,created_at DESC);
